content.text:
	});
}

/** The values of every `extensions:` input in the documentation's YAML examples. */
function extensionExamples(): { file: string; value: string }[] {
	return markdownFiles().flatMap((file) => {
		const text = read(file);
		const blocks = [...text.matchAll(EXTENSIONS_BLOCK_PATTERN)].map(
			([, , value = ""]) => ({ file, value }),
		);
		const lines = [...text.matchAll(EXTENSIONS_LINE_PATTERN)].map(
			([, value = ""]) => ({ file, value }),
		);
		return [...blocks, ...lines];
	});
}

describe("documentation", () => {
	it.each(markdownFiles())("%s has no broken relative links", (file) => {
		expect(brokenLinks(file)).toStrictEqual([]);
	});

	it("replaces every template variable that docs/prompts.md lists", () => {
		const documented = [
			...read("docs/prompts.md").matchAll(VARIABLE_ROW_PATTERN),
		].flatMap(([, name]) => (name ? [name] : []));
		expect(documented.length).toBeGreaterThan(0);
		const rendered = renderTemplate(
			documented.map((name) => `{{${name}}}`).join("\n"),
			{
				type: "pull_request",
				title: "t",
				body: "b",
				number: 1,
				task: "k",
				triggerComment: "c",
				diff: "d",
				reviewComments: "r",
			},
		);
		expect(rendered).not.toMatch(PLACEHOLDER_PATTERN);
		expect(rendered.split("\n")).toHaveLength(documented.length);
	});

	it("has extensions examples that pi-action can parse", () => {
		const examples = extensionExamples();
		expect(examples.length).toBeGreaterThan(0);
		for (const { file, value } of examples) {
			const specs = parseExtensionSpecs(value);
			expect(specs.length, `${file}: ${value}`).toBeGreaterThan(0);
			for (const spec of specs) {
				expect(() => classifySpec(spec, "/workspace"), file).not.toThrow();
			}
		}
	});
});
